(() => {
  'use strict';const L=window.IndoorLab,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  class ResidentWorkbench{
    constructor(api){this.api=api;this.comparison=null;this.viewing='after';this.applyProfile();$('resident-profile').onchange=()=>{this.applyProfile();this.invalidate();api.reset();};
      for(const key of ['width','length','speed','reach','maxHeight','doorEffort'])$('resident-'+key).onchange=()=>{this.invalidate();api.reset();};
      $('resident-task-list').onchange=()=>{if(!this.ids().length){document.querySelector('#resident-task-list input').checked=true;api.toast('至少保留一个任务。');}this.invalidate();api.reset();};
      $('resident-run').onclick=()=>{api.reset();api.play(true);};$('resident-repair').onclick=()=>this.repair();$('resident-restore').onclick=()=>this.restore();$('resident-before').onclick=()=>this.showVariant('before');$('resident-after').onclick=()=>this.showVariant('after');$('resident-export').onclick=()=>this.export();
      $('operation-mode').onchange=()=>{if(this.enabled()&&!api.state().model?.editableHome){$('demo-preset').value='home';api.loadDemo();}else api.reset();};
    }
    enabled(){return $('operation-mode').value==='resident';}
    ids(){return[...document.querySelectorAll('#resident-task-list input:checked')].map(i=>i.value);}
    profile(){const p={...L.RESIDENT_PROFILES[$('resident-profile').value]};for(const key of ['width','length','speed','reach','maxHeight','doorEffort']){const input=$('resident-'+key),n=Number(input.value);p[key]=L.clamp(Number.isFinite(n)?n:p[key],Number(input.min),Number(input.max));input.value=p[key];}return p;}
    applyProfile(){const p=L.RESIDENT_PROFILES[$('resident-profile').value];for(const key of ['width','length','speed','reach','maxHeight','doorEffort'])$('resident-'+key).value=p[key];$('resident-profile-note').textContent=p.type==='blind'?'熟悉住宅布局的任务导航；加入白杖探测与沿墙确认耗时。未模拟未知建筑自主建图。':p.type==='wheelchair'?'矩形轮椅包络＋转向扫掠、门前退让、低位触达及侧向转移检查。':p.type==='assisted'?'助行器占用、较慢步态、转向、门前操作与转移空间检查。':'缩小的触达范围与操作阻力阈值；分别检查能到达和能操作。';}
    invalidate(){this.comparison=null;this.viewing='after';}
    build(grid,model,prepared){if(this.enabled()&&!model.editableHome){$('operation-mode').value='crowd';this.invalidate();}const active=this.enabled();document.body.classList.toggle('resident-mode',active);if(active)return new L.ResidentSimulation(grid,model,this.profile(),this.ids(),prepared);for(const d of model.doors||[])model.setDoor(d.id,1);return null;}
    render(sim){if(!sim?.isResident)return;const result=sim.results[Math.min(sim.taskIndex,sim.results.length-1)],agent=sim.agents[0];$('resident-live').textContent=(sim.finished?'本轮执行结束':`任务 ${sim.taskIndex+1}/${sim.results.length} · ${result.name}`)+' / '+(agent.action||'等待执行');
      const revision=JSON.stringify(sim.results.map(r=>[r.task,r.success,r.duration,r.issues]));if(this.resultRevision!==revision){this.resultRevision=revision;$('resident-table').innerHTML='<table class="task-table"><thead><tr><th>任务</th><th>计划结果</th><th>尝试耗时</th></tr></thead><tbody>'+sim.results.map(r=>`<tr><td>${esc(r.name)}</td><td class="${r.success?'task-pass':'task-fail'}">${r.success?'可完成':'受阻'}</td><td>${r.duration.toFixed(1)} s</td></tr><tr class="task-reason"><td colspan="3">${r.success?`最小包络余量 ${(r.minClearance*100).toFixed(1)} cm`:esc(r.issues[0]?.reason||'未完成')}</td></tr>`).join('')+'</tbody></table><p class="hint">表格为几何与动作执行器的预测结果；点击执行后按原始轨迹播放，不预填提升值。</p>';}
      const c=this.comparison;document.body.classList.toggle('resident-comparing',!!c);const signature=c?JSON.stringify([c.beforeSummary,c.afterSummary,c.changes,this.viewing]):'';if(this.compareRevision!==signature){this.compareRevision=signature;$('resident-comparison').innerHTML=c?this.comparisonHTML(c):'<p class="hint">运行修复 Agent 后，这里会对比固定画像、相同任务与起点的量化结果。任务耗时仅在前后均完成时计算改善。</p>';$('resident-changes').innerHTML=c?'<h4>已应用修改</h4>'+c.changes.map(p=>`<p><b>${esc(p.title)}</b><br>${esc(p.description)}</p>`).join('')+(c.changes.length?'':'<p>候选未改善评分，场景未修改。</p>')+`<p class="hint">验证了 ${c.audit.length} 个候选。尺寸方案为内置参数商品，不是真实在售 SKU。仍受阻的任务继续显示，不保证自动修复全部问题。</p>`:'';}
      for(const id of ['resident-before','resident-after','resident-restore'])$(id).disabled=!c;
    }
    comparisonHTML(c){const b=c.beforeSummary,a=c.afterSummary,rows=[['完成任务',`${b.completed}/${b.tasks}`,`${a.completed}/${a.tasks}`],['碰撞尝试',b.collisions,a.collisions],['转向失败',b.turnFailures,a.turnFailures],['路径失败',b.pathFailures,a.pathFailures],['触达失败',b.reachFailures,a.reachFailures],['开门失败',b.doorFailures,a.doorFailures],['转移失败',b.transferFailures,a.transferFailures],['最小包络余量',(b.minClearance*100).toFixed(1)+' cm',(a.minClearance*100).toFixed(1)+' cm']];const common=c.before.map((r,i)=>r.success&&c.after[i].success?{b:r.duration,a:c.after[i].duration}:null).filter(Boolean);if(common.length)rows.push(['共同完成任务耗时',common.reduce((s,r)=>s+r.b,0).toFixed(1)+' s',common.reduce((s,r)=>s+r.a,0).toFixed(1)+' s']);return`<h4>修改前后对比 · ${this.viewing==='before'?'正在查看修改前':'正在查看修改后'}</h4><table class="task-table"><thead><tr><th>指标</th><th>前</th><th>后</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table><p class="hint">${esc(c.method)}${common.length?'':'前后尚无共同完成任务，耗时改善不适用。'}</p>`;}
    async repair(){const state=this.api.state();if(state.busy||!state.model?.editableHome)return;this.api.busy(true,'修复 Agent 正在建立基线…');try{const c=await L.repairResidentHome(state.model,state.grid,this.profile(),this.ids(),message=>$('loading-text').textContent=message);this.comparison=c;this.viewing='after';await this.api.install(c.model,c.grid,c.after);this.api.toast(`已复测：完成任务 ${c.beforeSummary.completed} → ${c.afterSummary.completed} / ${c.taskIds.length}；应用 ${c.changes.length} 项修改。`);}catch(error){this.api.toast(error.message,true);console.error(error);}finally{this.api.busy(false);this.api.play(false);}}
    async showVariant(which){const c=this.comparison;if(!c||this.api.state().busy)return;this.api.busy(true,'正在切换对比场景…');try{this.viewing=which;await this.api.install(L.makeResidentHome(which==='before'?c.baseSpec:c.afterSpec),null,which==='before'?c.before:c.after);}finally{this.api.busy(false);this.api.play(false);}}
    async restore(){const c=this.comparison;if(!c)return;const spec=c.baseSpec;this.invalidate();this.api.busy(true);try{await this.api.install(L.makeResidentHome(spec));}finally{this.api.busy(false);this.api.play(false);}}
    export(){const s=this.api.state().sim;if(!s?.isResident)return;const c=this.comparison,trim=results=>results.map(r=>({...r}));const data={schema:'resident-trials/1',createdAt:new Date().toISOString(),profile:this.profile(),taskIds:this.ids(),cellSize:this.api.state().grid.cell,results:trim(s.results),comparison:c?{before:trim(c.before),after:trim(c.after),beforeSummary:c.beforeSummary,afterSummary:c.afterSummary,changes:c.changes,audit:c.audit,baseSpec:c.baseSpec,afterSpec:c.afterSpec,method:c.method}:null,limitations:'单一水平地面上的包络、扫掠和触达假设；非人体动力学或规范认证；本任务模块只修复内置有语义住宅，不自动识别导入网格的商品和门。'};this.api.download('ACCESS-resident-tasks.json',JSON.stringify(data,null,2),'application/json');}
  }
  L.ResidentWorkbench=ResidentWorkbench;
})();



